"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import {
  DayPicker,
  getDefaultClassNames,
  type DayButton,
  type Locale,
} from "react-day-picker"

import { Button, buttonVariants } from "@/components/ui/button"
import { ArrowLeft01Icon, ArrowRight01Icon, ArrowDown01Icon } from "@hugeicons/core-free-icons"
import { HaloIcon } from "@/components/icons/halo-icon"

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  buttonVariant = "ghost",
  locale,
  formatters,
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: React.ComponentProps<typeof Button>["variant"]
}) {
  const defaultClassNames = getDefaultClassNames()

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn(
        "group/calendar bg-background p-2 [--cell-radius:var(--radius-md)] [--cell-size:--spacing(7)] in-data-[slot=card-content]:bg-transparent in-data-[slot=popover-content]:bg-transparent in-data-[slot=date-picker-content]:bg-transparent in-data-[slot=date-range-picker-content]:bg-transparent in-[[data-slot]]:bg-transparent",
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className
      )}
      captionLayout={captionLayout}
      locale={locale}
      formatters={{
        formatMonthDropdown: (date) =>
          date.toLocaleString(locale?.code, { month: "short" }),
        ...formatters,
      }}
      classNames={{
        root: cn("w-fit", defaultClassNames.root),
        months: cn(
          "relative flex flex-col gap-4 md:flex-row",
          defaultClassNames.months
        ),
        month: cn("flex w-full flex-col gap-4", defaultClassNames.month),
        nav: cn(
          "absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1",
          defaultClassNames.nav
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) p-0 select-none rounded-xl text-muted-foreground hover:text-foreground hover:bg-white/15 dark:hover:bg-white/10 active:scale-95 transition-all aria-disabled:opacity-40",
          defaultClassNames.button_previous
        ),
        button_next: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) p-0 select-none rounded-xl text-muted-foreground hover:text-foreground hover:bg-white/15 dark:hover:bg-white/10 active:scale-95 transition-all aria-disabled:opacity-40",
          defaultClassNames.button_next
        ),
        month_caption: cn(
          "flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)",
          defaultClassNames.month_caption
        ),
        dropdowns: cn(
          "flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium",
          defaultClassNames.dropdowns
        ),
        dropdown_root: cn(
          "relative rounded-(--cell-radius)",
          defaultClassNames.dropdown_root
        ),
        dropdown: cn(
          "absolute inset-0 bg-popover opacity-0",
          defaultClassNames.dropdown
        ),
        caption_label: cn(
          "font-semibold select-none text-foreground text-sm tracking-tight",
          captionLayout === "label"
            ? "text-sm"
            : "flex items-center gap-1 rounded-(--cell-radius) text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground",
          defaultClassNames.caption_label
        ),
        month_grid: cn("w-full border-collapse", defaultClassNames.month_grid),
        weekdays: cn("flex pb-1 border-b border-black/[0.06] dark:border-white/[0.08]", defaultClassNames.weekdays),
        weekday: cn(
          "flex-1 rounded-(--cell-radius) text-[0.75rem] font-semibold text-muted-foreground/75 select-none text-center",
          defaultClassNames.weekday
        ),
        week: cn("mt-1.5 flex w-full", defaultClassNames.week),
        week_number_header: cn(
          "w-(--cell-size) select-none",
          defaultClassNames.week_number_header
        ),
        week_number: cn(
          "text-[0.8rem] text-muted-foreground select-none",
          defaultClassNames.week_number
        ),
        day: cn(
          "group/day relative aspect-square h-full w-full rounded-(--cell-radius) p-0 text-center select-none [&:last-child[data-selected=true]_button]:rounded-r-(--cell-radius)",
          props.showWeekNumber
            ? "[&:nth-child(2)[data-selected=true]_button]:rounded-l-(--cell-radius)"
            : "[&:first-child[data-selected=true]_button]:rounded-l-(--cell-radius)",
          defaultClassNames.day
        ),
        range_start: cn(
          "relative isolate z-0 rounded-l-(--cell-radius) bg-muted after:absolute after:inset-y-0 after:right-0 after:w-4 after:bg-muted",
          defaultClassNames.range_start
        ),
        range_middle: cn("rounded-none", defaultClassNames.range_middle),
        range_end: cn(
          "relative isolate z-0 rounded-r-(--cell-radius) bg-muted after:absolute after:inset-y-0 after:left-0 after:w-4 after:bg-muted",
          defaultClassNames.range_end
        ),
        today: cn(
          "rounded-(--cell-radius) bg-muted text-foreground data-[selected=true]:rounded-none",
          defaultClassNames.today
        ),
        outside: cn(
          "text-muted-foreground aria-selected:text-muted-foreground",
          defaultClassNames.outside
        ),
        disabled: cn(
          "text-muted-foreground opacity-50",
          defaultClassNames.disabled
        ),
        hidden: cn("invisible", defaultClassNames.hidden),
        ...classNames,
      }}
      components={{
        Root: ({ className, rootRef, ...props }) => {
          return (
            <div
              data-slot="calendar"
              ref={rootRef}
              className={cn(className)}
              {...props}
            />
          )
        },
        Chevron: ({ className, orientation, ...props }) => {
          if (orientation === "left") {
            return (
              <HaloIcon icon={ArrowLeft01Icon} size={16} className={cn("size-4", className)} {...props} />
            )
          }

          if (orientation === "right") {
            return (
              <HaloIcon icon={ArrowRight01Icon} size={16} className={cn("size-4", className)} {...props} />
            )
          }

          return (
            <HaloIcon icon={ArrowDown01Icon} size={16} className={cn("size-4", className)} {...props} />
          )
        },
        DayButton: ({ ...props }) => (
          <CalendarDayButton locale={locale} {...props} />
        ),
        WeekNumber: ({ children, ...props }) => {
          return (
            <td {...props}>
              <div className="flex size-(--cell-size) items-center justify-center text-center">
                {children}
              </div>
            </td>
          )
        },
        ...components,
      }}
      {...props}
    />
  )
}

function CalendarDayButton({
  className,
  day,
  modifiers,
  locale,
  ...props
}: React.ComponentProps<typeof DayButton> & { locale?: Partial<Locale> }) {
  const defaultClassNames = getDefaultClassNames()

  const ref = React.useRef<HTMLButtonElement>(null)
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <Button
      variant="ghost"
      size="icon"
      data-day={day.date.toLocaleDateString(locale?.code)}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        "relative isolate z-10 flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 border-0 leading-none font-normal rounded-xl transition-all duration-150 select-none",
        "hover:bg-white/20 dark:hover:bg-white/10 hover:text-foreground",
        // Focus state
        "group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-ring group-data-[focused=true]/day:ring-[2px] group-data-[focused=true]/day:ring-ring/50",
        // Single Selected Day: HaloUI Optical Specular Pill
        "data-[selected-single=true]:bg-foreground data-[selected-single=true]:text-background data-[selected-single=true]:font-bold",
        "data-[selected-single=true]:shadow-[0_2px_10px_rgba(255,255,255,0.4),inset_0_1px_1px_rgba(255,255,255,0.8)] dark:data-[selected-single=true]:shadow-[0_2px_12px_rgba(255,255,255,0.25),inset_0_1px_1px_rgba(255,255,255,0.4)]",
        "data-[selected-single=true]:hover:bg-foreground data-[selected-single=true]:hover:text-background",
        // Today Indicator (when not selected)
        modifiers.today && !modifiers.selected && "font-bold text-foreground ring-1 ring-foreground/25 bg-white/10 dark:bg-white/[0.06]",
        // Range Selection
        "data-[range-start=true]:rounded-l-xl data-[range-start=true]:rounded-r-none data-[range-start=true]:bg-foreground data-[range-start=true]:text-background data-[range-start=true]:font-bold",
        "data-[range-end=true]:rounded-r-xl data-[range-end=true]:rounded-l-none data-[range-end=true]:bg-foreground data-[range-end=true]:text-background data-[range-end=true]:font-bold",
        "data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-white/20 dark:data-[range-middle=true]:bg-white/10 data-[range-middle=true]:text-foreground",
        defaultClassNames.day,
        className
      )}
      {...props}
    />
  )
}

export { Calendar, CalendarDayButton }

/**
 * HaloUI Liquid Material Design System Tokens
 * Physical optical material engine: refraction, specular highlight, optical edges,
 * neoskeuomorphic depth, tactile compression, and virtual directional lighting.
 */

:root {
  /* Surface Tints (Light Mode: Luminous warm translucent body) */
  --halo-surface: rgba(255, 255, 255, 0.72);
  --halo-surface-elevated: rgba(255, 255, 255, 0.88);
  --halo-surface-strong: rgba(255, 255, 255, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.03);
  --halo-surface-tint: rgba(245, 245, 247, 0.45);

  /* Optical Edges (Light Mode: Fine micro-reflections) */
  --halo-edge: rgba(255, 255, 255, 0.9);
  --halo-edge-soft: rgba(0, 0, 0, 0.08);
  --halo-edge-bright: rgba(255, 255, 255, 1);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.9), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.06);

  /* Specular Highlights (Directional: Virtual light at 135deg / top-left) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0.15) 35%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;

  /* Optical Blur (Backdrop Diffusion) */
  --halo-blur-sm: 8px;
  --halo-blur-md: 16px;
  --halo-blur-lg: 28px;
  --halo-blur-xl: 44px;

  /* Shadows (Contact & Ambient anchoring) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.08), 0 2px 4px 0 rgba(0, 0, 0, 0.04);
  --halo-shadow-elevated: 0 6px 16px -4px rgba(0, 0, 0, 0.08), 0 2px 6px -1px rgba(0, 0, 0, 0.04);
  --halo-shadow-ambient: 0 16px 36px -8px rgba(0, 0, 0, 0.1);
  --halo-shadow-compressed: 0 1px 1px 0 rgba(0, 0, 0, 0.1);

  /* Refraction Parameters */
  --halo-refraction-strength: 0.12;
  --halo-refraction-offset: 1.5px;
  --halo-noise-opacity: 0.025;
  --halo-glow: rgba(0, 0, 0, 0.04);

  /* Corner Radii */
  --halo-radius-sm: 8px;
  --halo-radius-md: 12px;
  --halo-radius-lg: 18px;
  --halo-radius-xl: 26px;
  --halo-radius-full: 9999px;

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #0284c7;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Motion Presets & Timing Architecture */
  --halo-duration-micro: 120ms;
  --halo-duration-state: 180ms;
  --halo-duration-reveal: 240ms;
  --halo-duration-settle: 320ms;
  --halo-ease-tactile: cubic-bezier(0.2, 0.8, 0.3, 1);
  --halo-ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --halo-ease-out: cubic-bezier(0, 0, 0.2, 1);

  /* Typography & Canvas (Editorial warm tone) */
  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;
}

.dark {
  /* Surface Tints (Dark Mode: Deep graphite optical body) */
  --halo-surface: rgba(22, 23, 26, 0.7);
  --halo-surface-elevated: rgba(30, 32, 38, 0.85);
  --halo-surface-strong: rgba(38, 41, 48, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.45);
  --halo-surface-tint: rgba(18, 19, 22, 0.6);

  /* Optical Edges (Dark Mode: Luminous rim catch & dark contact) */
  --halo-edge: rgba(255, 255, 255, 0.14);
  --halo-edge-soft: rgba(255, 255, 255, 0.06);
  --halo-edge-bright: rgba(255, 255, 255, 0.28);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.2), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.6);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);

  /* Specular Highlights (Directional top-left luminescence) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.04) 38%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;

  /* Shadows (Deep graphite depth) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.4), 0 3px 6px 0 rgba(0, 0, 0, 0.3);
  --halo-shadow-elevated: 0 8px 24px -4px rgba(0, 0, 0, 0.65), 0 3px 8px -2px rgba(0, 0, 0, 0.4);
  --halo-shadow-ambient: 0 20px 48px -12px rgba(0, 0, 0, 0.85);
  --halo-shadow-compressed: 0 1px 2px 0 rgba(0, 0, 0, 0.6);

  --halo-refraction-strength: 0.18;
  --halo-noise-opacity: 0.035;
  --halo-glow: rgba(255, 255, 255, 0.04);

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #38bdf8;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Typography & Canvas */
  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;
}

/* Explicit Stage Scopes for Interactive Previews */
.light,
[data-stage-theme="light"] {
  --halo-surface: rgba(255, 255, 255, 0.72);
  --halo-surface-elevated: rgba(255, 255, 255, 0.88);
  --halo-surface-strong: rgba(255, 255, 255, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.03);
  --halo-surface-tint: rgba(245, 245, 247, 0.45);

  --halo-edge: rgba(255, 255, 255, 0.9);
  --halo-edge-soft: rgba(0, 0, 0, 0.08);
  --halo-edge-bright: rgba(255, 255, 255, 1);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.9), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.06);

  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0.15) 35%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;

  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.08), 0 2px 4px 0 rgba(0, 0, 0, 0.04);
  --halo-shadow-elevated: 0 6px 16px -4px rgba(0, 0, 0, 0.08), 0 2px 6px -1px rgba(0, 0, 0, 0.04);
  --halo-shadow-ambient: 0 16px 36px -8px rgba(0, 0, 0, 0.1);
  --halo-shadow-compressed: 0 1px 1px 0 rgba(0, 0, 0, 0.1);

  --halo-refraction-strength: 0.12;
  --halo-noise-opacity: 0.025;
  --halo-glow: rgba(0, 0, 0, 0.04);

  --halo-focus-color: #0284c7;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);

  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;

  /* Scoped semantic background / foreground for light stage */
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --border: oklch(0.922 0 0);
  --muted-foreground: oklch(0.556 0 0);
  color-scheme: light;
}

[data-stage-theme="dark"] {
  --halo-surface: rgba(22, 23, 26, 0.7);
  --halo-surface-elevated: rgba(30, 32, 38, 0.85);
  --halo-surface-strong: rgba(38, 41, 48, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.45);
  --halo-surface-tint: rgba(18, 19, 22, 0.6);

  --halo-edge: rgba(255, 255, 255, 0.14);
  --halo-edge-soft: rgba(255, 255, 255, 0.06);
  --halo-edge-bright: rgba(255, 255, 255, 0.28);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.2), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.6);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);

  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.04) 38%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;

  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.4), 0 3px 6px 0 rgba(0, 0, 0, 0.3);
  --halo-shadow-elevated: 0 8px 24px -4px rgba(0, 0, 0, 0.65), 0 3px 8px -2px rgba(0, 0, 0, 0.4);
  --halo-shadow-ambient: 0 20px 48px -12px rgba(0, 0, 0, 0.85);
  --halo-shadow-compressed: 0 1px 2px 0 rgba(0, 0, 0, 0.6);

  --halo-refraction-strength: 0.18;
  --halo-noise-opacity: 0.035;
  --halo-glow: rgba(255, 255, 255, 0.04);

  --halo-focus-color: #38bdf8;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);

  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;

  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --card: oklch(0.145 0 0);
  --card-foreground: oklch(0.985 0 0);
  --border: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  color-scheme: dark;
}

/* Material Intensity Presets */
.halo-intensity-subtle {
  --halo-active-blur: var(--halo-blur-sm);
  --halo-active-highlight: 0.4;
  --halo-active-edge: 0.7;
}

.halo-intensity-balanced {
  --halo-active-blur: var(--halo-blur-md);
  --halo-active-highlight: 0.85;
  --halo-active-edge: 1;
}

.halo-intensity-rich {
  --halo-active-blur: var(--halo-blur-lg);
  --halo-active-highlight: 1.2;
  --halo-active-edge: 1.35;
}

/* Tactile Physics Classes */
.halo-tactile-press {
  transition: transform 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              box-shadow 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              background-color 150ms ease;
}

.halo-tactile-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
  box-shadow: var(--halo-shadow-compressed), var(--halo-edge-inner), var(--halo-edge-outer) !important;
}

/* Focus Ring Accessibility Infrastructure */
.halo-focus-ring {
  outline: none;
}

.halo-focus-ring:focus-visible {
  outline: 2px solid var(--halo-focus-color) !important;
  outline-offset: var(--halo-focus-offset) !important;
  box-shadow: var(--halo-focus-shadow) !important;
  z-index: 10;
}

/* Forced Colors (High Contrast Mode) */
@media (forced-colors: active) {
  .halo-focus-ring:focus-visible {
    outline: 2px solid Highlight !important;
    outline-offset: 2px !important;
    box-shadow: none !important;
  }
}

/* Motion Presets Classes */
.halo-motion-press {
  transition: transform var(--halo-duration-micro) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-micro) var(--halo-ease-tactile);
}

.halo-motion-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
}

.halo-motion-lift {
  transition: transform var(--halo-duration-state) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-state) var(--halo-ease-tactile);
}

.halo-motion-lift:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--halo-shadow-elevated);
}

.halo-motion-reveal {
  animation: halo-reveal var(--halo-duration-reveal) var(--halo-ease-spring) forwards;
}

.halo-motion-settle {
  transition: transform var(--halo-duration-settle) var(--halo-ease-spring),
              opacity var(--halo-duration-reveal) ease;
}

.halo-motion-float {
  animation: halo-float 3.5s ease-in-out infinite alternate;
}

@keyframes halo-reveal {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes halo-float {
  0% {
    transform: translateY(0px);
  }
  100% {
    transform: translateY(-6px);
  }
}

/* Reduced Motion Override */
@media (prefers-reduced-motion: reduce) {
  .halo-tactile-press,
  .halo-motion-press,
  .halo-motion-lift,
  .halo-motion-reveal,
  .halo-motion-settle,
  .halo-motion-float,
  .halo-motion-transition {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transform: none !important;
  }
}

